// a value that does not parse stays NaN and the check step says so.
function readRow(r) {
  return {
    sku:        String(r.sku || '').trim(),
    style:      String(r.style || '').trim().toLowerCase(),
    purity_k:   num(r.purity_k),
    length_in:  num(r.length_in),
    weight_g:   num(r.weight_g),
    qty:        num(r.qty),
    prev_price: num(r.price),
    prev_rate:  num(r.rate),
    prev_qty:   num(r.priced_qty),
    priced_at:  String(r.priced_at || '').trim()
  };
}

function priceChain(row, rate24, cfg) {
  const purity = cfg.purity[row.purity_k];
  const style = cfg.styles[row.style];
  const metal = row.weight_g * purity * rate24;
  const making = row.weight_g * style.making_per_gram;
  const gross = (metal + making) * (1 + cfg.wholesale_margin_pct / 100);
  const step = cfg.round_to || 1;
  return {
    metal_value: Math.round(metal * 100) / 100,
    making_value: Math.round(making * 100) / 100,
    price: Math.round(gross / step) * step
  };
}

function money(v, cfg) {
  return cfg.currency_symbol + Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

function chainLabel(row, cfg) {
  const style = cfg.styles[row.style];
  return row.purity_k + 'k ' + (style ? style.label : row.style) + ' ' + row.length_in + 'in';
}
// ---- end shared pricing ----
const today = new Date().toISOString().slice(0, 10);
const byStyle = {};
for (const c of j.chains) (byStyle[c.style] = byStyle[c.style] || []).push(c);
const styleOrder = Object.keys(cfg.styles).filter((s) => byStyle[s]);
const sortChains = (a, b) => a.purity_k - b.purity_k || a.length_in - b.length_in || a.weight_g - b.weight_g;

// 22k is what most wholesale buyers quote in, so it is stated as well as 24k.
const rate22 = Math.round(j.rate_24k * cfg.purity[22] * 100) / 100;
const rateLine = '24k ' + money(j.rate_24k, cfg) + '/g · 22k ' + money(rate22, cfg) + '/g';
const demoTag = /DEMO/.test(j.rate_source) ? ' (DEMO RATE, NOT A MARKET PRICE)' : '';

const line = (c) => '• ' + c.purity_k + 'k ' + c.length_in + 'in · ' + c.weight_g + ' g · ' +
  money(c.price, cfg) + ' · ' + c.qty + (c.qty === 1 ? ' pc' : ' pcs');

const catalogue = ['*' + cfg.business_name + ', ' + today + '*', rateLine + demoTag, ''];
for (const s of styleOrder) {
  const inStock = byStyle[s].filter((c) => c.qty > 0).sort(sortChains);
  if (!inStock.length) continue;
  catalogue.push('*' + cfg.styles[s].label + '*');
  for (const c of inStock) catalogue.push(line(c));
  catalogue.push('');
}
catalogue.push("Prices at today's rate, valid today. Reply with the chain you want.");

const stock_list = j.chains.slice().sort((a, b) => (a.sku < b.sku ? -1 : 1))
  .map((c) => c.sku.padEnd(8) + ' ' + c.label.padEnd(18) + ' ' + String(c.weight_g).padStart(5) +
    ' g  ' + String(c.qty).padStart(3) + ' pcs  ' + money(c.price, cfg));

const csvCell = (v) => (/[",\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v));
const stock_csv = [['sku', 'style', 'purity_k', 'length_in', 'weight_g', 'qty', 'price', 'currency', 'rate_24k', 'priced_on']]
  .concat(j.chains.map((c) => [c.sku, c.style, c.purity_k, c.length_in, c.weight_g, c.qty, c.price, cfg.currency, j.rate_24k, today]))
  .map((r) => r.map(csvCell).join(',')).join('\n');

// The announcement: the rate, then only what changed. Short enough to read on a phone.
const pick = (kind) => j.chains.filter((c) => c.change === kind).sort(sortChains);
const ann = ['*' + cfg.business_name + "*: today's rate", rateLine + demoTag];
if (j.rate_move_pct !== null) ann.push('(' + (j.rate_move_pct >= 0 ? 'up ' : 'down ') + Math.abs(j.rate_move_pct) + '% since our last list)');
const section = (title, list, fmt) => {
  if (!list.length) return;
  ann.push('', '*' + title + '*');
  list.forEach((c) => ann.push(fmt(c)));
};
section('New in', pick('new'), (c) => '• ' + c.label + ' · ' + c.weight_g + ' g · ' + money(c.price, cfg));
section('Back in stock', pick('back in stock'), (c) => '• ' + c.label + ' · ' + c.weight_g + ' g · ' + money(c.price, cfg));
section('Last few', pick('last few'), (c) => '• ' + c.label + ' · ' + c.qty + ' left · ' + money(c.price, cfg));
section('Sold out', pick('sold out'), (c) => '• ' + c.label);
ann.push('', "Reply with the chain you want for today's price.");
let announcement = ann.join('\n');
// WhatsApp over Twilio caps a message at 1,600 characters. Cut at a line, and say so.
if (announcement.length > 1500) {
  announcement = announcement.slice(0, 1450).replace(/\n[^\n]*$/, '') + '\n...and more. Reply for the full list.';
}

return [{ json: Object.assign({}, j, {
  today, rate_22k: rate22,
  catalogue: catalogue.join('\n').trim(),
  stock_list: stock_list.join('\n'),
  stock_csv,
  announcement,
  counts: {
    priced: j.chains.length, in_stock: j.chains.filter((c) => c.qty > 0).length,
    new: pick('new').length, back_in_stock: pick('back in stock').length,
    last_few: pick('last few').length, sold_out: pick('sold out').length, held_back: j.held.length
  }
}) }];

// The Customers tab, one item per row, collected into one item in the same shape as the demo.
const customers = $input.all().map((i) => i.json || {}).filter((r) => String(r.whatsapp || '').trim() !== '');
return [{ json: { source: 'customers sheet', customers } }];

// No sheet configured, so the invented demo customers stand in, in the same shape as the sheet.
const cfg = $('config').first().json;
return [{ json: { source: 'demo customers (invented)', customers: cfg.demo_customers } }];

// Decides who receives the announcement, and says why for everyone who does not:
//   opted out            -> never messaged
//   not a usable number  -> skipped, listed for someone to fix
//   duplicate number     -> sent once
//   over BROADCAST_CAP   -> not sent this time, listed
// In test mode every message is redirected to TEST_WHATSAPP, at most test_cap of them, and
// marked [TEST]. The owner's approval request is built here too; the approve link itself is
// added on the send node, because only n8n knows it at that moment.
const cfg = $('config').first().json;
const draft = $('build the catalogue').first().json;
const list = ($input.first().json || {}).customers || [];

function e164(v) {
  const s = String(v || '').replace(/^whatsapp:/, '').replace(/[\s()\-.]/g, '');
  return /^\+[1-9]\d{7,14}$/.test(s) ? s : '';
}
const yes = (v) => /^(y|yes|true|1|x)$/i.test(String(v || '').trim());

const sends = [], skipped = [], seen = new Set();
for (const c of list) {
  const to = e164(c.whatsapp);
  if (yes(c.opted_out)) { skipped.push({ name: c.name, why: 'opted out' }); continue; }
  if (!to) { skipped.push({ name: c.name, why: 'not a usable number: ' + c.whatsapp }); continue; }
  if (seen.has(to)) { skipped.push({ name: c.name, why: 'duplicate number' }); continue; }
  if (sends.length >= cfg.broadcast_cap) { skipped.push({ name: c.name, why: 'over BROADCAST_CAP ' + cfg.broadcast_cap }); continue; }
  seen.add(to);
  sends.push({ name: c.name, to, body: draft.announcement });
}

let planned = sends;
if (cfg.mode === 'test') {
  planned = sends.slice(0, cfg.test_cap).map((s) => ({
    name: s.name, to: e164(cfg.test_whatsapp),
    body: '[TEST: would go to ' + s.name + ' ' + s.to + ']\n' + s.body
  }));
}

const owner_to = cfg.mode === 'test' ? e164(cfg.test_whatsapp) : e164(cfg.owner_whatsapp);
const owner_message = [
  (cfg.mode === 'test' ? '[TEST] ' : '') + "Today's list is ready: " + draft.counts.in_stock + ' chains in stock, ' +
    draft.counts.new + ' new, ' + draft.counts.sold_out + ' sold out' +
    (draft.counts.held_back ? ', ' + draft.counts.held_back + ' held back (see the run)' : '') + '.',
  'Rate: ' + draft.rate_note + '.',
  'It goes to ' + planned.length + ' customer(s) when you approve. Nothing is sent without you.',
  '', '--- the message ---', draft.announcement
].join('\n');

return [{ json: {
  mode: cfg.mode, owner_to, owner_message,
  sends: planned, would_send_live: sends.length, skipped,
  customers_source: ($input.first().json || {}).source
} }];

// Sending is off (TEST_RUN is true with TEST_WHATSAPP blank, or no Twilio sender). Nothing
// was sent to anyone. This node IS the result: the catalogue, the stock list, the owner's
// approval request and every customer message, exactly as they would have gone.
const cfg = $('config').first().json;
const d = $('build the catalogue').first().json;
const p = $input.first().json;
return [{ json: {
  _outcome: 'preview: nothing sent',
  _reason: cfg.twilio_whatsapp_from ? 'mode is ' + cfg.mode : 'no TWILIO_WHATSAPP_FROM, preview only',
  rate: d.rate_24k + ' ' + d.currency + '/g 24k, ' + d.rate_source + ', ' + d.rate_note,
  counts: d.counts,
  held_back: d.held,
  catalogue: d.catalogue,
  stock_list: d.stock_list,
  stock_csv: d.stock_csv,
  owner_approval_request: p.owner_message,
  broadcast_to: p.sends.map((s) => s.name + ' ' + s.to),
  not_sent_to: p.skipped
} }];

// APPROVAL_WAIT_HOURS passed without the owner opening the approve link. Nothing is sent:
// a morning price list sent in the evening is a wrong price list.
const cfg = $('config').first().json;
return [{ json: { _outcome: 'not sent', _reason: 'no approval within ' + cfg.approval_wait_hours + ' hour(s)' } }];

// The owner approved. One item per recipient, exactly as planned before the approval was
// asked for: nothing is re-priced after the owner has seen it.
const p = $('plan the broadcast').first().json;
return p.sends.map((s) => ({ json: { name: s.name, to: s.to, body: s.body } }));

// The broadcast went out after the owner approved it. Everyone left off, and why, is listed.
const n = $input.all().length;
const p = $('plan the broadcast').first().json;
return [{ json: { _outcome: 'sent', _reason: n + ' announcement(s) sent after the owner approved',
  mode: p.mode, not_sent_to: p.skipped } }];

// What gets written back to the Stock tab: today's price, rate and quantity, so the NEXT run
// can tell what is new and what sold out. Matched on sku; no other column is touched.
const j = $('build the catalogue').first().json;
return j.chains.map((c) => ({ json: {
  sku: c.sku, price: c.price, rate: j.rate_24k, priced_qty: c.qty, priced_at: j.today
} }));

// The Stock tab now carries today's price, rate and quantity for every priced chain.
const n = $input.all().length;
return [{ json: { _outcome: 'written', _reason: n + " stock row(s) updated with today's price and rate" } }];

// The sheet is only written live (TEST_RUN = false and a SHEET_ID set). Nothing was written;
// this is exactly what would have been.
const j = $('build the catalogue').first().json;
const cfg = $('config').first().json;
return [{ json: {
  _outcome: 'preview: sheet not written',
  _reason: cfg.sheet_enabled ? 'mode is ' + cfg.mode + '; the sheet is only written live'
                             : 'no SHEET_ID, running on the demo stock',
  would_write: j.chains.map((c) => ({ sku: c.sku, price: c.price, rate: j.rate_24k, priced_qty: c.qty, priced_at: j.today }))
} }];
